import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"seed Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"seed","tag":"seed","title":"seed Tag","prev":null,"next":null,"posts":[{"title":"伪随机的种子问题","url":"/posts/2018-08-01-random-seed/","date":"2018-08-01 22:07","tags":["random","seed"],"html":"<p>最近前端的工作不是很多，所以就帮忙写写后端的 ruby on rails。在写测试用例的时候，虽然单元测试的数据每次都是随机生成的，但是我们需要根据单元测试来生成 API 文档。如果测试文档每次都是随机的数据会很难检查每次 API 更新了什么，所以我们需要在生产测试文档的时候，保证随机数据的稳定性。</p>\\n<h2 id=\\"random-seed\\" tabindex=\\"-1\\">Random seed <a class=\\"header-anchor\\" href=\\"#random-seed\\" aria-label=\\"Permalink to &quot;Random seed&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>seed 的意义就在于，初始化了随机数生成器。保证了每次随机的结果都一样。例如代码：</p>\\n<div class=\\"language-rb line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">rb</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">@rand </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> Random</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#D73A49\\">new</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">1234</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">..</span><span style=\\"color:#005CC5\\">1050</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">..</span><span style=\\"color:#005CC5\\">1050</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>这段代码每次执行都会输出：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>0.1915194503788923</span></span>\\n<span class=\\"line\\"><span>674</span></span>\\n<span class=\\"line\\"><span>699</span></span>\\n<span class=\\"line\\"><span>0.2725926052826416</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><h2 id=\\"rand-range\\" tabindex=\\"-1\\">rand range <a class=\\"header-anchor\\" href=\\"#rand-range\\" aria-label=\\"Permalink to &quot;rand range&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>但是当我们把中间的 rand 的范围稍微修改：</p>\\n<div class=\\"language-rb line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">rb</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">@rand </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> Random</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#D73A49\\">new</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">1234</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">10</span><span style=\\"color:#24292E\\">..</span><span style=\\"color:#005CC5\\">150</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">10</span><span style=\\"color:#24292E\\">..</span><span style=\\"color:#005CC5\\">150</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>会发现输出发生了变化：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>0.1915194503788923</span></span>\\n<span class=\\"line\\"><span>48</span></span>\\n<span class=\\"line\\"><span>63</span></span>\\n<span class=\\"line\\"><span>0.4377277390071145</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>第一次的输出还是不变，当然 2,3 两次肯定是变化的，重点是最后一次。我们发现最后一次的随机数也发生了变化。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>通过调查 ruby 源码发现，对于有范围的 rand。ruby 会不断生成随机数，判断是否落在区间范围内，如果是在范围内就返回，否则继续尝试。默认在 0 到 1 之间是百分百命中，所以是随机一次。如果是其他范围，命中次数不一样会导致生成随机数的次数发生变化。所以影响到之后的随机数生成。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://github.com/ruby/ruby/blob/trunk/random.c#L863\\" target=\\"_blank\\" rel=\\"noreferrer\\">ruby</a></p>\\n<p><a href=\\"https://ruby-doc.org/core-2.2.0/Random.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Random</a></p>\\n"}]},"relativePath":"tags/seed/index.md","filePath":"tags/[slug].md"}'),p={name:"tags/seed/index.md"};function e(l,r,o,c,t,i){return n(),a("div")}const u=s(p,[["render",e]]);export{b as __pageData,u as default};
